// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Define colors
const colors = [
  '#ff6b6b', // red
  '#4ecdc4', // blue
  '#45b7d1', // purple
  '#96ceb4', // green
  '#feca57', // yellow
  '#ff9ff3'  // pink
];

// Draw circles with different colors
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 20;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fillStyle = colors[i % 6];
  ctx.fill();
}

// Draw inner circle
ctx.beginPath();
ctx.arc(centerX, centerY, maxRadius - 30, 0, Math.PI * 2);
ctx.fillStyle = '#ffffff';
ctx.fill();

// Draw central pattern
ctx.beginPath();
ctx.arc(centerX, centerY, 15, 0, Math.PI * 2);
ctx.fillStyle = '#ff6b6b';
ctx.fill();

// Draw lines connecting circles
ctx.strokeStyle = '#ff6b6b';
ctx.lineWidth = 2;
for (let i = 0; i < 6; i++) {
  const angle = (i / 6) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * (maxRadius - 30);
  const startY = centerY + Math.sin(angle) * (maxRadius - 30);
  const endX = centerX + Math.cos(angle) * maxRadius;
  const endY = centerY + Math.sin(angle) * maxRadius;

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

// Draw additional lines for depth
ctx.strokeStyle = '#4ecdc4';
ctx.lineWidth = 1;
for (let i = 0; i < 6; i++) {
  const angle = (i / 6) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * (maxRadius - 30);
  const startY = centerY + Math.sin(angle) * (maxRadius - 30);
  const endX = centerX + Math.cos(angle) * (maxRadius + 10);
  const endY = centerY + Math.sin(angle) * (maxRadius + 10);

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.stroke();
}

