// Draw spiral
function drawSpiral(x, y, size, angle, iterations) {
    if (iterations === 0) return;

    // Draw current segment
    ctx.fillStyle = `hsl(${100 + Math.sin(angle) * 30}, 70%, 30%)`;
    ctx.fillRect(x, y, size, size);

    // Recursive calls for next segments
    drawSpiral(
        x - size * Math.cos(angle),
        y - size * Math.sin(angle),
        size * 0.7,
        angle + 0.3,
        iterations - 1
    );
}

// Start drawing spiral from center
